package com.jnapanam.sportszone.tournament.service;
import com.jnapanam.sportszone.catalog.model.*;import com.jnapanam.sportszone.catalog.repository.*;import com.jnapanam.sportszone.common.exception.*;import com.jnapanam.sportszone.identity.model.User;import com.jnapanam.sportszone.identity.repository.UserRepository;import com.jnapanam.sportszone.tournament.dto.*;import com.jnapanam.sportszone.tournament.model.*;import com.jnapanam.sportszone.tournament.repository.*;import java.time.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class TournamentService{
 private final OrganizerApplicationRepository applications;private final TournamentRepository tournaments;private final TournamentTeamRepository teams;private final TournamentTeamMemberRepository members;private final TournamentFixtureRepository fixtures;private final UserRepository users;private final SportRepository sports;private final FacilityRepository facilities;private final long paymentMinutes;
 public TournamentService(OrganizerApplicationRepository a,TournamentRepository t,TournamentTeamRepository teams,TournamentTeamMemberRepository m,TournamentFixtureRepository f,UserRepository u,SportRepository s,FacilityRepository facilities,@Value("${app.payment.pending-minutes:15}")long paymentMinutes){applications=a;tournaments=t;this.teams=teams;members=m;fixtures=f;users=u;sports=s;this.facilities=facilities;this.paymentMinutes=paymentMinutes;}
 @Transactional public OrganizerApplicationResponse apply(UUID userId,OrganizerApplicationRequest r){if(applications.existsByUserIdAndStatusIn(userId,List.of(OrganizerStatus.PENDING,OrganizerStatus.APPROVED)))throw new ConflictException("An open or approved organizer application already exists");return OrganizerApplicationResponse.from(applications.save(new OrganizerApplication(user(userId),r.organizationName(),r.experience(),r.contactNumber())));}
 @Transactional(readOnly=true)public List<OrganizerApplicationResponse>applications(){return applications.findAllByOrderByAppliedAtDesc().stream().map(OrganizerApplicationResponse::from).toList();}
 @Transactional public OrganizerApplicationResponse review(UUID id,OrganizerReviewRequest r){if(r.status()==OrganizerStatus.PENDING)throw new BadRequestException("Review must approve or reject the application");OrganizerApplication a=applications.findById(id).orElseThrow(()->new NotFoundException("Organizer application not found"));if(a.getStatus()!=OrganizerStatus.PENDING)throw new ConflictException("Application is already reviewed");a.review(r.status(),r.reviewNote());return OrganizerApplicationResponse.from(a);}
 @Transactional public TournamentResponse create(TournamentRequest r){validateDates(r);if(tournaments.existsByCodeIgnoreCase(r.code()))throw new ConflictException("Tournament code already exists");User organizer=user(r.organizerUserId());if(!applications.existsByUserIdAndStatus(r.organizerUserId(),OrganizerStatus.APPROVED))throw new ConflictException("Organizer is not approved");Sport sport=sports.findByCodeIgnoreCase(r.sportCode()).orElseThrow(()->new NotFoundException("Sport not found"));Tournament t=new Tournament(r.code(),r.name(),r.description(),sport,organizer,r.format(),r.registrationOpens(),r.registrationCloses(),r.startDate(),r.endDate(),r.teamSize(),r.maxTeams(),r.entryFee());return response(tournaments.save(t));}
 @Transactional public TournamentResponse update(UUID id,TournamentRequest r){validateDates(r);Tournament t=tournament(id);if(!t.getCode().equalsIgnoreCase(r.code()))throw new BadRequestException("Tournament code cannot be changed");User organizer=user(r.organizerUserId());if(!applications.existsByUserIdAndStatus(r.organizerUserId(),OrganizerStatus.APPROVED))throw new ConflictException("Organizer is not approved");Sport sport=sports.findByCodeIgnoreCase(r.sportCode()).orElseThrow(()->new NotFoundException("Sport not found"));long registered=teams.countByTournamentIdAndStatus(t.getId(),TeamStatus.REGISTERED);if(r.maxTeams()<registered)throw new BadRequestException("Maximum teams cannot be lower than registered teams");t.update(r.name(),r.description(),sport,organizer,r.format(),r.registrationOpens(),r.registrationCloses(),r.startDate(),r.endDate(),r.teamSize(),r.maxTeams(),r.entryFee());return response(t);}
 @Transactional public TournamentResponse status(UUID id,TournamentStatusRequest r){Tournament t=tournament(id);t.status(r.status());return response(t);}
 @Transactional(readOnly=true)public List<TournamentResponse>publicList(){return tournaments.findByStatusInOrderByStartDateAsc(List.of(TournamentStatus.PUBLISHED,TournamentStatus.REGISTRATION_OPEN,TournamentStatus.REGISTRATION_CLOSED,TournamentStatus.IN_PROGRESS,TournamentStatus.COMPLETED)).stream().map(this::response).toList();}
 @Transactional(readOnly=true)public List<TournamentResponse>all(){return tournaments.findAllByOrderByStartDateDesc().stream().map(this::response).toList();}
 @Transactional public TeamResponse register(UUID userId,UUID tournamentId,TeamRegistrationRequest r){Tournament t=tournament(tournamentId);if(t.getStatus()!=TournamentStatus.REGISTRATION_OPEN)throw new ConflictException("Tournament registration is not open");LocalDate now=LocalDate.now();if(now.isBefore(t.getRegistrationOpens())||now.isAfter(t.getRegistrationCloses()))throw new ConflictException("Tournament registration window is closed");if(r.members().size()!=t.getTeamSize())throw new BadRequestException("Team must contain exactly "+t.getTeamSize()+" members");List<TeamStatus>active=List.of(TeamStatus.REGISTERED,TeamStatus.PENDING_PAYMENT);if(teams.countByTournamentIdAndStatusIn(tournamentId,active)>=t.getMaxTeams())throw new ConflictException("Tournament is full");if(teams.existsByTournamentIdAndNameIgnoreCaseAndStatusIn(tournamentId,r.teamName(),active))throw new ConflictException("Team name already exists");if(teams.existsByTournamentIdAndCaptainIdAndStatusIn(tournamentId,userId,active))throw new ConflictException("Captain already registered a team");boolean paymentRequired=t.getEntryFee().signum()>0;TournamentTeam team=teams.save(new TournamentTeam(t,user(userId),r.teamName(),paymentRequired,Instant.now().plusSeconds(paymentMinutes*60)));for(var m:r.members())members.save(new TournamentTeamMember(team,m.name(),m.email(),m.mobile()));return team(team);}
 @Transactional(readOnly=true)public List<TeamResponse>mine(UUID userId){return teams.findByCaptainIdOrderByRegisteredAtDesc(userId).stream().map(this::team).toList();}
 @Transactional(readOnly=true)public List<TeamResponse>teams(UUID tournamentId){return teams.findByTournamentIdAndStatusOrderByRegisteredAtAsc(tournamentId,TeamStatus.REGISTERED).stream().map(this::team).toList();}
 @Transactional public List<FixtureResponse>generate(UUID tournamentId){Tournament t=tournament(tournamentId);if(fixtures.existsByTournamentId(tournamentId))throw new ConflictException("Fixtures already exist");List<TournamentTeam> registered=teams.findByTournamentIdAndStatusOrderByRegisteredAtAsc(tournamentId,TeamStatus.REGISTERED);if(registered.size()<2)throw new ConflictException("At least two teams are required");int match=1;if(t.getFormat()==TournamentFormat.LEAGUE){for(int i=0;i<registered.size();i++)for(int j=i+1;j<registered.size();j++)fixtures.save(new TournamentFixture(t,1,match++,registered.get(i),registered.get(j)));}else{for(int i=0;i<registered.size();i+=2)fixtures.save(new TournamentFixture(t,1,match++,registered.get(i),i+1<registered.size()?registered.get(i+1):null));}t.status(TournamentStatus.REGISTRATION_CLOSED);return fixtureList(tournamentId);}
 @Transactional public FixtureResponse schedule(UUID id,FixtureScheduleRequest r){TournamentFixture f=fixture(id);Facility facility=r.facilityId()==null?null:facilities.findById(r.facilityId()).orElseThrow(()->new NotFoundException("Facility not found"));f.schedule(facility,r.scheduledAt());return FixtureResponse.from(f);}
 @Transactional public FixtureResponse result(UUID id,FixtureResultRequest r){TournamentFixture f=fixture(id);if(f.getTournament().getFormat()==TournamentFormat.SINGLE_ELIMINATION&&r.homeScore()==r.awayScore())throw new BadRequestException("Elimination match cannot end in a draw");f.result(r.homeScore(),r.awayScore());return FixtureResponse.from(f);}
 @Transactional(readOnly=true)public List<FixtureResponse>fixtureList(UUID tournamentId){tournament(tournamentId);return fixtures.findByTournamentIdOrderByRoundNumberAscMatchNumberAsc(tournamentId).stream().map(FixtureResponse::from).toList();}
 @Transactional public int cleanupUnpaid(){int count=0;for(TournamentTeam t:teams.findByStatusAndPaymentExpiresAtLessThanEqual(TeamStatus.PENDING_PAYMENT,Instant.now())){t.expirePayment();count++;}return count;}
 private TournamentResponse response(Tournament t){return TournamentResponse.from(t,teams.countByTournamentIdAndStatus(t.getId(),TeamStatus.REGISTERED));}private TeamResponse team(TournamentTeam t){return TeamResponse.from(t,members.findByTeamIdOrderByCreatedAtAsc(t.getId()));}private Tournament tournament(UUID id){return tournaments.findById(id).orElseThrow(()->new NotFoundException("Tournament not found"));}private TournamentFixture fixture(UUID id){return fixtures.findById(id).orElseThrow(()->new NotFoundException("Fixture not found"));}private User user(UUID id){return users.findById(id).orElseThrow(()->new NotFoundException("User not found"));}
 private static void validateDates(TournamentRequest r){if(r.registrationCloses().isBefore(r.registrationOpens())||r.startDate().isBefore(r.registrationCloses())||r.endDate().isBefore(r.startDate()))throw new BadRequestException("Tournament dates are invalid");}
}
